import { describe, expect, it } from 'vitest';
import kanjiData from './kanji_data.json';
import type { KanjiItem } from '../types/kanji';
import type { StrokeFile } from '../utils/strokes';

// Everything under public/strokes, generated by build_strokes.py
const files = import.meta.glob<StrokeFile>('../../public/strokes/*.json', { eager: true, import: 'default' });
const byCode = new Map(Object.entries(files).map(([path, file]) => [path.match(/([0-9a-f]+)\.json$/)![1], file]));
const data = kanjiData as KanjiItem[];

/**
 * Kanji added to the Jōyō list in 2010 that KanjiVG draws in the traditional form
 * (two-dot 辶, 飠 instead of 食, …) or counts differently. The player explains the difference;
 * if this list changes, the data changed and the note should be rechecked.
 */
const KNOWN_COUNT_DIFFERENCES = ['謎', '餌', '僅', '餅', '遜', '遡', '葛', '賭', '牙'];

describe('stroke data', () => {
  it('ships a stroke file for every kanji in the dataset', () => {
    const missing = data.filter((k) => !byCode.has(k.code)).map((k) => k.c);
    expect(missing).toEqual([]);
  });

  it('has a number position for every stroke, inside the 109 × 109 box', () => {
    for (const k of data) {
      const file = byCode.get(k.code)!;
      expect(file.s.length, k.c).toBeGreaterThan(0);
      expect(file.n, k.c).toHaveLength(file.s.length);
      for (const pos of file.n) {
        expect(pos, k.c).not.toBeNull();
        const [x, y] = pos!;
        expect(x >= 0 && x <= 109 && y >= 0 && y <= 109, `${k.c} ${x},${y}`).toBe(true);
      }
    }
  });

  it('only disagrees with the dataset stroke count for the known traditional forms', () => {
    const differing = data.filter((k) => byCode.get(k.code)!.s.length !== k.st).map((k) => k.c);
    expect(differing.sort()).toEqual([...KNOWN_COUNT_DIFFERENCES].sort());
  });
});
